include('../config.php');require_once __DIR__.'/../base/CraftingPolicy.class.php';$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$s=new Game();if(!$s->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];if(empty($_SESSION['craft_csrf']))$_SESSION['craft_csrf']=bin2hex(random_bytes(16));$csrf=$_SESSION['craft_csrf'];$notice='';$error='';$db->query("INSERT IGNORE INTO player_resource_wallet(uid) VALUES($uid)");if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Security validation failed.';elseif(($_POST['craft_action']??'')==='craft'){$key=(string)($_POST['equipment_key']??'');$r=CraftingPolicy::recipe($key);$currentQ=$db->query("SELECT level FROM player_equipment WHERE uid=$uid AND equipment_key='".$db->real_escape_string($key)."' LIMIT 1");$current=(int)(($currentQ&&$currentQ->num_rows)?$currentQ->fetch_assoc()['level']:0);$next=$current+1;$cost=$r?CraftingPolicy::cost($key,$next):[];$w=$db->query("SELECT metal,crystal,energy FROM player_resource_wallet WHERE uid=$uid LIMIT 1")->fetch_assoc();if(!$r||$next>CraftingPolicy::MAX_LEVEL)$error='Equipment level is invalid or already at maximum.';elseif((int)$w['metal']<$cost['metal']||(int)$w['crystal']<$cost['crystal']||(int)$w['energy']<$cost['energy'])$error='Insufficient resources for this upgrade.';else{$db->begin_transaction();$ok=$db->query("UPDATE player_resource_wallet SET metal=metal-{$cost['metal']},crystal=crystal-{$cost['crystal']},energy=energy-{$cost['energy']} WHERE uid=$uid AND metal>={$cost['metal']} AND crystal>={$cost['crystal']} AND energy>={$cost['energy']} LIMIT 1");$st=$db->prepare("INSERT INTO player_equipment(uid,equipment_key,level,quantity) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE level=VALUES(level),quantity=quantity+1");$st->bind_param('isi',$uid,$key,$next);$ok=$ok&&$st->execute();$st2=$db->prepare('INSERT INTO crafting_transactions(uid,equipment_key,level,metal_cost,crystal_cost,energy_cost) VALUES(?,?,?,?,?,?)');$st2->bind_param('isiiii',$uid,$key,$next,$cost['metal'],$cost['crystal'],$cost['energy']);$ok=$ok&&$st2->execute();if($ok){$db->commit();$notice='Crafted '.$r['name'].' level '.$next.'.';}else{$db->rollback();$error='Crafting transaction failed.';}}}}
$wallet=$db->query("SELECT metal,crystal,energy FROM player_resource_wallet WHERE uid=$uid LIMIT 1")->fetch_assoc();$equipment=$db->query("SELECT equipment_key,level,quantity FROM player_equipment WHERE uid=$uid ORDER BY equipment_key");echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // ARMORY FABRICATION</span><h3>Player Crafting and Equipment</h3><p>Upgrade individual unit modules and improve fleet combat performance.</p></div>';if($notice)echo '<div class="comm-alert">'.htmlspecialchars($notice,ENT_QUOTES,'UTF-8').'</div>';if($error)echo '<div class="comm-alert comm-error">'.htmlspecialchars($error,ENT_QUOTES,'UTF-8').'</div>';echo '<section class="comm-card"><h4>Resource Wallet</h4><p>Metal '.number_format((int)$wallet['metal']).' · Crystal '.number_format((int)$wallet['crystal']).' · Energy '.number_format((int)$wallet['energy']).'</p></section><section class="comm-card"><h4>Equipment Upgrade Bay</h4><div class="admin-table-wrap"><table><tr><th>Module</th><th>Level</th><th>Quantity</th><th>Per-level effect</th><th>Upgrade</th></tr>';foreach(CraftingPolicy::RECIPES as $key=>$r){$level=0;$qty=0;if($equipment){$equipment->data_seek(0);while($e=$equipment->fetch_assoc())if($e['equipment_key']===$key){$level=(int)$e['level'];$qty=(int)$e['quantity'];break;}}echo '<tr><td>'.htmlspecialchars($r['name'],ENT_QUOTES,'UTF-8').'</td><td>'.$level.'/'.CraftingPolicy::MAX_LEVEL.'</td><td>'.number_format($qty).'</td><td>Attack +'.$r['attack'].' · Defense +'.$r['defense'].' · Capacity +'.$r['capacity'].'</td><td><form method="post" action="modules/crafting.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.htmlspecialchars($csrf,ENT_QUOTES,'UTF-8').'"/><input type="hidden" name="craft_action" value="craft"/><input type="hidden" name="equipment_key" value="'.$key.'"/><button class="comm-btn">Craft Upgrade</button></form></td></tr>';}echo '</table></div></section></div>'; $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
